TC = "sennheiser-tcc2"
# Sennheiser SSC v1 on the TeamConnect Ceiling 2 (TI 1245 v1.8.0): one JSON message
# per UDP datagram to port 45, answered to the sender with the values the device
# now holds, or an /osc/error entry.

def t(command, input, wire, device_reply=None, **extra):
    if device_reply is not None:
        extra["device_reply_hex"] = device_reply.encode().hex()
        extra.setdefault("expect_result", {"ok": {"kind": "ack"}})
    text(TC, command, input, wire, **extra)


def datagram(name, inbound, **extra):
    telemetry(TC, name, inbound_hex=inbound.encode().hex(), **extra)


